from pyriemann.estimation import Covariances
from pyriemann.tangentspace import TangentSpace
from pyriemann.classification import MDM
from pyriemann.geometry.mean import mean_logeuclid as pr_mean
from pyriemann.geometry.tangentspace import tangent_space as pr_ts
from pyriemann.geometry.covariance import covariances

@test
def test_covariances():
    X = signals(6, 4, 50)
    assert close(covariances(X, estimator="cov"), E_cov_cov)
    assert close(covariances(X, estimator="scm"), E_cov_scm)
    assert close(covariances(X, estimator="lwf"), E_cov_lwf)
    assert close(covariances(X, estimator="oas"), E_cov_oas)
    assert close(covariances(X, estimator="sch"), E_cov_sch)
    assert close(covariances(X, estimator="corr"), E_cov_corr)
test_covariances()

@test
def test_pipeline():
    X = signals(40, 8, 256)
    y = np.array([i % 2 for i in range(40)])
    scm = Covariances("cov").fit_transform(X)
    oas = Covariances("oas").fit_transform(X)
    assert scm.shape == (40, 8, 8)
    assert close(scm[0], E_pipe_scm0)
    assert close(oas[0], E_pipe_oas0)
    pm = pr_mean(oas)
    assert close(pm, E_pipe_pm)
    T = TangentSpace(metric="logeuclid").fit(scm).transform(scm)
    assert T.shape == (40, 36)
    assert close(T[:2], E_pipe_ts_rows02, atol=1e-11)
    assert abs(float(T.sum()) - E_pipe_ts_sum) < 1e-10
    ts2 = pr_ts(oas, pm, metric="riemann")
    assert close(ts2[:2], E_pipe_prts_rows01, atol=1e-11)
    assert closef(float(ts2.sum()), E_pipe_prts_sum, rtol=1e-9)
    preds = np.zeros(40, dtype=int)
    for k in range(5):
        te = np.arange(k * 8, (k + 1) * 8)
        mask = np.ones(40, dtype=bool)
        mask[k * 8:(k + 1) * 8] = False
        clf = MDM(metric="logeuclid").fit(scm[mask], y[mask])
        preds[te] = clf.predict(scm[te])
        if k == 0:
            assert close(clf.predict_proba(scm[te]), E_mdm_fold0_proba)
            assert close(clf.transform(scm[te]), E_mdm_fold0_transform)
            assert close(clf.covmeans_, E_mdm_fold0_covmeans)
            assert closef(clf.score(scm[te], y[te]), E_mdm_fold0_score)
            assert clf.classes_.shape == (2,)
    assert close(preds, [float(v) for v in E_mdm_preds])
    clf = MDM().fit(scm, y)
    assert close(clf.transform(scm[:3]), E_mdm_riemann_transform03, rtol=1e-9)
    ts = TangentSpace()
    Tr = ts.fit_transform(scm[:10])
    assert close(ts.inverse_transform(Tr), scm[:10].ravel().tolist(), atol=1e-11)
test_pipeline()
